// Families the user belongs to (as owner or as accepted spouse) through an active spouse link.
func (q *Queries) ListUserFamilies(ctx context.Context, arg ListUserFamiliesParams) ([]Family, error) {
	rows, err := q.db.QueryContext(ctx, listUserFamilies, arg.OwnerID, arg.SpouseUserID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Family{}
	for rows.Next() {
		var i Family
		if err := rows.Scan(
			&i.ID,
			&i.OwnerID,
			&i.SpouseUserID,
			&i.CompanionID,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

